/*
 * A371279  Irregular triangular array of numerators of the set T of fractions
 *          generated by these rules: g(1) = (1), and if x and y are in T,
 *          then x/(y+1) is in T; see Comments.
 * https://oeis.org/A371279
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf, frac
 * Formula:   not stated
 * Range:     u8 n <= 80, u16 n <= 80, u32 n <= 80, u64 n <= 80, u128 n <= 80,
 *            big any n
 * Helpers:   gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A371279: numerators of fractions generated from 1/1 by the rule
 * x/(y+1).  Fractions are stored in generation order; a(n) is the
 * numerator of the nth fraction produced. */
#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/gcd.h"

typedef struct { seq_t num; seq_t den; } frac_t;

static frac_t *seen = NULL;
static size_t seen_cap = 0, seen_len = 0;
static frac_t *next = NULL;
static size_t next_cap = 0, next_len = 0;

#define HASH_CAP (1 << 18)

static bool *hash_used = NULL;
static seq_t *hash_num = NULL;
static seq_t *hash_den = NULL;
static bool init_done = false;

static inline size_t hash_ratio(seq_t num, seq_t den)
{
    unsigned long long hn = (unsigned long long)num;
    unsigned long long hd = (unsigned long long)den;
    size_t h = (size_t)(hn ^ (hd << 32));
    return h & (HASH_CAP - 1);
}

static inline bool hash_exists(seq_t num, seq_t den)
{
    size_t i = hash_ratio(num, den);
    while (hash_used[i]) {
        if (hash_num[i] == num && hash_den[i] == den) return true;
        i = (i + 1) & (HASH_CAP - 1);
    }
    return false;
}

static inline void hash_insert(seq_t num, seq_t den)
{
    size_t i = hash_ratio(num, den);
    while (hash_used[i]) {
        if (hash_num[i] == num && hash_den[i] == den) return;
        i = (i + 1) & (HASH_CAP - 1);
    }
    hash_used[i] = true;
    hash_num[i] = num;
    hash_den[i] = den;
}

static void init_once(void)
{
    if (init_done) return;
    init_done = true;

    hash_used = (bool*)calloc(HASH_CAP, sizeof(bool));
    hash_num  = (seq_t*)calloc(HASH_CAP, sizeof(seq_t));
    hash_den  = (seq_t*)calloc(HASH_CAP, sizeof(seq_t));

    seen_cap = 4;
    seen = (frac_t*)malloc(seen_cap * sizeof(frac_t));
    seq_t one = (seq_t)1;
    seen[0].num = one;
    seen[0].den = one;
    seen_len = 1;
    hash_insert(one, one);

    next_cap = 4;
    next = (frac_t*)malloc(next_cap * sizeof(frac_t));
    next_len = 0;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;
    init_once();

    while (seen_len < (size_t)n) {
        size_t m = seen_len;
        size_t cap_needed = m * m;
        if (next_cap < cap_needed) {
            size_t newcap = next_cap ? next_cap << 1 : 4;
            while (newcap < cap_needed) newcap <<= 1;
            next = (frac_t*)realloc(next, newcap * sizeof(frac_t));
            next_cap = newcap;
        }
        next_len = 0;

        for (size_t i = 0; i < m; ++i) {
            seq_t xi = seen[i].num;
            seq_t yi = seen[i].den;
            for (size_t j = 0; j < m; ++j) {
                seq_t yk = seen[j].num;
                seq_t dk = seen[j].den;

                seq_t num = xi * dk;
                seq_t den = yi * (yk + dk);
                seq_t g = gcd(num, den);
                num /= g;
                den /= g;

                if (hash_exists(num, den)) continue;
                hash_insert(num, den);
                next[next_len].num = num;
                next[next_len].den = den;
                ++next_len;
            }
        }

        if (seen_cap < seen_len + next_len) {
            size_t newcap = seen_cap ? seen_cap << 1 : 4;
            while (newcap < seen_len + next_len) newcap <<= 1;
            seen = (frac_t*)realloc(seen, newcap * sizeof(frac_t));
            seen_cap = newcap;
        }
        for (size_t k = 0; k < next_len; ++k) {
            seen[seen_len + k] = next[k];
        }
        seen_len += next_len;
    }
    return seen[n - 1].num;
}
